(function(g){'use strict';
const VERSION=1;
function fresh(){return {version:VERSION,language:'both',records:{},stars:[],exams:[],session:null,archive:{},updatedAt:Date.now()};}
function shuffle(list,rng=Math.random){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function mockQuestions(bank,n=50,rng=Math.random){const verified=bank.filter(q=>q.verified);if(verified.length<n)throw Error('已核对题目不足');const groups={};verified.forEach(q=>(groups[q.category]??=[]).push(q));const chosen=[];Object.values(groups).forEach(a=>chosen.push(shuffle(a,rng)[0]));const ids=new Set(chosen.map(q=>q.id));return shuffle([...chosen,...shuffle(verified.filter(q=>!ids.has(q.id)),rng).slice(0,n-chosen.length)],rng).slice(0,n).map(q=>q.id);}
function record(state,id,correct,answer){const r=state.records[id]??{attempts:0,correct:0,errors:0,streak:0,wrong:false};r.attempts++;r.correct+=correct?1:0;r.lastAnswer=answer;r.lastAt=Date.now();if(!correct){r.errors++;r.wrong=true;r.streak=0;delete state.archive[id];}else if(r.wrong){r.streak++;if(r.streak>=2){r.wrong=false;state.archive[id]=Date.now();}}state.records[id]=r;return r;}
function newSession(mode,ids,minutes=0,feedback='exam'){return {id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9),mode,feedback:mode==='mock'&&feedback!=='immediate'?'exam':'immediate',ids:[...ids],index:0,answers:{},recorded:{},startedAt:Date.now(),deadline:minutes>0?Date.now()+minutes*60000:null,completed:false};}
function answerPractice(state,bank,id,answer){const s=state.session,q=bank.find(q=>q.id===id);if(!s||s.mode==='mock'&&s.feedback!=='immediate'||s.completed||!s.ids.includes(id)||!q||!Number.isInteger(answer)||answer<0||answer>=q.options.length||s.recorded[id])return false;s.answers[id]=answer;s.recorded[id]=true;record(state,id,answer===q.answer,answer);return true;}
function enableImmediateFeedback(state,bank){const s=state.session;if(!s||s.mode!=='mock'||s.completed)return false;s.feedback='immediate';for(const id of s.ids){const q=bank.find(q=>q.id===id),a=s.answers[id];if(q&&Number.isInteger(a)&&a>=0&&a<q.options.length&&!s.recorded[id]){s.recorded[id]=true;record(state,id,a===q.answer,a);}}return true;}
function finishMock(state,bank,reason='manual'){const s=state.session;if(!s||s.mode!=='mock'||s.completed)return null;let score=0;for(const id of s.ids){const q=bank.find(q=>q.id===id);const a=s.answers[id]??null;const correct=a===q.answer;score+=correct?1:0;if(!s.recorded[id]){record(state,id,correct,a);s.recorded[id]=true;}}const result={id:s.id,ids:[...s.ids],answers:{...s.answers},feedback:s.feedback||'exam',score,total:s.ids.length,passed:score>=Math.ceil(s.ids.length*.8),finishedAt:Date.now(),duration:Math.max(0,Date.now()-s.startedAt),reason};s.completed=true;s.result=result;state.exams.unshift(result);state.exams=state.exams.slice(0,100);return result;}
function validateImport(data,bank){if(!data||data.version!==1||typeof data.records!=='object'||!data.records||Array.isArray(data.records)||!Array.isArray(data.stars)||!Array.isArray(data.exams))throw Error('备份格式不正确');const ids=new Set(bank.map(q=>q.id));const clean=fresh();clean.language=['both','zh','en'].includes(data.language)?data.language:'both';for(const [id,r]of Object.entries(data.records)){if(!ids.has(id))continue;if(!r||!['attempts','correct','errors','streak'].every(k=>Number.isSafeInteger(r[k])&&r[k]>=0)||r.correct+r.errors!==r.attempts)throw Error('答题记录损坏');clean.records[id]={attempts:r.attempts,correct:r.correct,errors:r.errors,streak:Math.min(2,r.streak),wrong:!!r.wrong,lastAnswer:Number.isInteger(r.lastAnswer)?r.lastAnswer:null,lastAt:Number(r.lastAt)||0};}clean.stars=[...new Set(data.stars.filter(id=>ids.has(id)))];clean.archive=Object.fromEntries(Object.entries(data.archive||{}).filter(([id,t])=>ids.has(id)&&Number.isFinite(t)));clean.exams=data.exams.filter(e=>e&&typeof e.id==='string'&&Array.isArray(e.ids)&&e.ids.length===50&&e.ids.every(id=>ids.has(id))&&e.total===50&&Number.isInteger(e.score)&&e.score>=0&&e.score<=50&&Number.isFinite(e.finishedAt)&&Number.isFinite(e.duration)&&e.answers&&typeof e.answers==='object'&&Object.entries(e.answers).every(([id,a])=>e.ids.includes(id)&&Number.isInteger(a)&&a>=0&&a<4)).slice(0,100).map(e=>({...e,passed:e.score>=40}));return clean;}
const api={fresh,shuffle,mockQuestions,record,newSession,answerPractice,enableImmediateFeedback,finishMock,validateImport};g.NJCore=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
